import { describe, expect, it } from 'vitest';
import { allFiniteBars, computeH0 } from '../../../src/lib/tda/index.ts';
import { loadFixture } from './helpers.ts';

/**
 * F3 criterion 5: TypeScript must reproduce pipeline/tda_ref.py exactly on the shared fixtures
 * (tests/fixtures/tda/agreement.json, generated by tests/fixtures/tda/generate_fixtures.py).
 * pipeline/tests/test_tda_ref.py checks the Python side against the same file.
 */

interface Case {
  id: number;
  kind: string;
  W: number;
  H: number;
  connectivity: 4 | 8;
  heights: number[];
  births: number;
  finite: [number, number, number][];
  essential: number[];
  zeroLength: number;
}

const { cases } = loadFixture<{ cases: Case[] }>('agreement.json');

describe('TypeScript ↔ Python agreement on shared fixtures', () => {
  it('has ≥ 200 4-connected grids, most with ties', () => {
    const four = cases.filter((c) => c.connectivity === 4);
    expect(four.length).toBeGreaterThanOrEqual(200);
    const withTies = four.filter((c) => new Set(c.heights).size < c.heights.length);
    expect(withTies.length).toBeGreaterThanOrEqual(190);
  });

  for (const c of cases) {
    it(`case ${c.id} (${c.kind}, ${c.W}×${c.H}, ${c.connectivity}-conn)`, () => {
      const h = new Float32Array(c.heights);
      const r = computeH0(h, c.W, c.H, { connectivity: c.connectivity });
      const finite = allFiniteBars(r);
      expect(finite.map((b) => [b.birthCell, b.deathCell, b.mergedInto])).toEqual(c.finite);
      const essential = r.bars.filter((b) => b.death === Infinity).map((b) => b.birthCell);
      expect(essential).toEqual(c.essential);
      expect(r.stats.births).toBe(c.births);
      expect(r.stats.zeroLength).toBe(c.zeroLength);
      for (const b of finite) {
        expect(b.birth).toBe(h[b.birthCell]);
        expect(b.death).toBe(h[b.deathCell]);
      }
    });
  }
});
